<fieldset class="border rounded p-3 mb-3 invoice-line"><legend class="float-none w-auto fs-6 px-2"><?= \App\Support\I18n::html('Product line') ?></legend><div class="row g-3"><div class="col-md-8"><label class="form-label" for="search-<?= $e($i) ?>"><?= \App\Support\I18n::html('Search product code or name') ?></label><input type="search" id="search-<?= $e($i) ?>" class="form-control mb-2 product-search" placeholder="<?= \App\Support\I18n::html('Type to find a product') ?>"><label class="form-label" for="product-<?= $e($i) ?>"><?= \App\Support\I18n::html('Product *') ?></label><select class="form-select invoice-product" name="items[<?= $e($i) ?>][product_id]" id="product-<?= $e($i) ?>" required><option value=""><?= \App\Support\I18n::html('Select an active product') ?></option><?php foreach($options['products'] as $p): ?><option data-name-si="<?= $e($p['name_si']??'') ?>" data-name="<?= $e($p['name']) ?>" data-sku="<?= $e($p['sku']) ?>" data-price="<?= $e($p['selling_price']) ?>" data-category="<?= $e($p['category']??'') ?>" data-quantity="<?= $e($p['available_quantity']) ?>" value="<?= $e($p['id']) ?>" <?= ($line['product_id']??'')===(string)$p['id']?'selected':'' ?>><?= $e($p['sku'].' — '.\App\Support\I18n::product($p).' · LKR '.$p['selling_price'].' · stock '.$p['available_quantity']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label" for="quantity-<?= $e($i) ?>"><?= \App\Support\I18n::html('Paid quantity *') ?></label><input class="form-control" id="quantity-<?= $e($i) ?>" name="items[<?= $e($i) ?>][quantity]" inputmode="numeric" pattern="[1-9][0-9]*" maxlength="19" required value="<?= $e($line['quantity']??'1') ?>"><button type="button" class="btn btn-outline-secondary btn-sm mt-3 remove-invoice-line"><?= \App\Support\I18n::html('Remove line') ?></button></div></div></fieldset>
